def build(destination):
 import hashlib
 tables=ROOT/'outputs/tables/dlm_selecionado';payload={};manifest=[]
 for name in ['painel','nacional','painel_perfis','nacional_perfis','painel_candidatos','nacional_candidatos','cobertura']:
  p=tables/(name+'.csv');df=pd.read_csv(p);payload[name]=df.astype(object).where(pd.notna(df),None).to_dict(orient='records');manifest.append(dict(fonte='dlm_selecionado/'+p.name,linhas=len(df),sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
 for name in ['nacional_diagnosticos','nacional_influencia','nacional_estabilidade','painel_conferencia']:
  path=ROOT/'outputs/tables/revisao_integrada'/(name+'.csv');df=pd.read_csv(path);payload['review_'+name]=df.astype(object).where(pd.notna(df),None).to_dict('records');manifest.append(dict(fonte='revisao_integrada/'+path.name,linhas=len(df),sha256=hashlib.sha256(path.read_bytes()).hexdigest()))
 payload['manifest']=manifest;payload['validacao']=json.loads((tables/'validacao.json').read_text())
 # Reuse presentation helpers only; no old model payload or old report sections.
 style=re.search(r'<style>(.*?)</style>',old.HTML,re.S).group(1)
 lines=old.HTML.splitlines()
 shared=next(line for line in lines if line.startswith("'use strict';const D="))
 shared+='\n'+'\n'.join(line for line in lines if line.startswith(('function table(','function download(','function csv(','function canvasEmpty(','function plot(')))
 shared+="\nconst perName=p=>p=='Total'?'Total (2013–2024)':'Pré-pandemia (até jan/2020)';"
 granger={}
 for name,file in [('gm','matriz42.csv'),('gc','coeficientes.csv')]:
  df=pd.read_csv(ROOT/'outputs/tables/granger_fechamento'/file)
  granger[name]=df.astype(object).where(pd.notna(df),None).to_dict(orient='records')
 encoded=json.dumps(payload,ensure_ascii=False,allow_nan=False,separators=(',',':')).replace('</','<\\/')
 gencoded=json.dumps(granger,ensure_ascii=False,allow_nan=False,separators=(',',':')).replace('</','<\\/')
 header='<header><div class="eyebrow">TCC • Isabella Viana Bambirra</div><h1>Desastres e inadimplência: DLMs clássicos</h1><p>Painel e nacional com coeficientes livres e janela selecionada por categoria e período. Granger preservado.</p></header>'
 base='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Desastres e inadimplência — DLMs clássicos</title><style>'+style+CSS+'</style></head><body>'+header+BODY+'<script id="report-data" type="application/json">'+gencoded+'</script><script id="selected-data" type="application/json">'+encoded+'</script><script>'+shared+'\n'+JS+'</script></body></html>'
 Path(destination).write_text(base);return destination
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--output',default=str(ROOT.parent/'relatorio_granger_dlm_integrado.html'));a=p.parse_args();print(build(a.output))
